steps.sql:
SELECT snapshot_month, brand_name, roe, net_profit_margin, asset_turnover
FROM retail_finance.v_dupont WHERE snapshot_month >= CONCAT(YEAR(CURDATE()), '-01')
ORDER BY snapshot_month, brand_name;

SELECT brand_name, roe, net_profit_margin, asset_turnover, roe_drag_factor
FROM retail_finance.v_dupont
WHERE snapshot_month = DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m') ORDER BY roe DESC;

SELECT brand_name, net_profit_margin, asset_turnover, equity_multiplier, roe, roe_drag_factor
FROM retail_finance.v_dupont
WHERE snapshot_month = DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m') ORDER BY roe ASC;

SELECT SUM(profit) AS gross_profit, SUM(return_amount) AS returns
FROM retail_finance.dws_sales_daily
WHERE DATE_FORMAT(snapshot_date, '%Y-%m') = DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m');

SELECT SUM(revenue) AS ytd_revenue FROM (SELECT snapshot_month AS month, SUM(order_count) AS order_count, SUM(revenue + return_amount) AS gmv, SUM(revenue) AS net_revenue, SUM(profit) AS gross_profit, ROUND(SUM(profit) / NULLIF(SUM(revenue), 0) * 100, 2) AS gross_margin_pct, ROUND(SUM(return_amount) / NULLIF(SUM(revenue + return_amount), 0) * 100, 2) AS return_rate_pct, SUM(return_amount) AS return_amount FROM retail_finance.dws_sales_monthly GROUP BY snapshot_month) dws_sales_monthly（按月汇总）
WHERE month >= DATE_FORMAT(DATE(CONCAT(YEAR(CURDATE()), '-01-01')), '%Y-%m')
  AND month <= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m');

SELECT SUM(budget_amount - payment_amount) AS remaining_budget
FROM retail_finance.dws_expense_monthly
WHERE snapshot_month >= DATE_FORMAT(CURDATE(), '%Y%m') + 0;

SELECT s.channel_name, SUM(s.revenue) AS revenue, SUM(s.profit) AS gross_profit
FROM retail_finance.dws_sales_daily s 
WHERE DATE_FORMAT(s.snapshot_date, '%Y%m%d')+0 BETWEEN 20250601 AND 20250618 GROUP BY s.channel_name ORDER BY revenue DESC;

SELECT ROUND(SUM(revenue) / NULLIF(SUM(order_count), 0), 2) AS promo_aov,
    ROUND(SUM(gmv) / NULLIF(SUM(order_count), 0), 2) AS promo_gmv_aov
FROM retail_finance.dws_sales_daily WHERE snapshot_date BETWEEN 20250601 AND 20250618;

SELECT i.category_name, SUM(s.revenue) AS promo_revenue, SUM(s.order_count) AS promo_orders
FROM retail_finance.dws_sales_daily s 
WHERE DATE_FORMAT(s.snapshot_date, '%Y%m%d')+0 BETWEEN 20250601 AND 20250618 GROUP BY i.category_name ORDER BY promo_orders DESC;

SELECT SUM(stock_amount) AS total_inv, AVG(turnover_days) AS avg_turnover
FROM retail_finance.dws_inventory_daily
WHERE date_id = (SELECT MAX(snapshot_date) FROM retail_finance.dws_inventory_daily);
